@Slf4j
@RestController
@RequestMapping("/api/files")
@RequiredArgsConstructor
@Tag(name = "Files", description = "File serving endpoints")
public class FileController {

    private final FileStorageService file_storage_service;

    @GetMapping("/{fileName}")
    @Operation(summary = "Get file by name")
    @ApiResponses(value = {
            @ApiResponse(responseCode = "200", description = "File found"),
            @ApiResponse(responseCode = "404", description = "File not found")
    })
    public ResponseEntity<Resource> getFile(@PathVariable String fileName) {
        Resource resource = file_storage_service.load(fileName);

        if (resource == null) {
            return ResponseEntity.notFound().build();
        }

        String contentType = file_storage_service.determineContentType(fileName);
        return ResponseEntity.ok()
                .contentType(MediaType.parseMediaType(contentType))
                .cacheControl(CacheControl.maxAge(365, TimeUnit.DAYS).cachePublic().immutable())
                .body(resource);
    }
}
